/* SITE COPY — photo embedded as a data URL so the live page
   always shows the picture. Canonical source: sketch-camera-reveal.js */
/* ============================================================
   VALUES REVEAL — camera motion interactive art for
   Caritas Wu Cheng-Chung College (CWCC)

   NO machine-learning needed. The camera watches for MOTION
   (simple frame differencing): wave your hands, dance, move —
   and wherever you move, the navy veil lifts and a photo of
   the school is revealed underneath, like a scratch card.
   The detector is noise-robust: a spot must keep moving on
   consecutive frames before it paints, so camera flicker or a
   still face never clears the veil by itself.
   The brush is a generous round dab (~24px) and light waves count,
   so kids can reveal the photo with happy enthusiastic waving —
   reaching 100% still takes a good few waves, but never a grind.
   Edges & corners are awkward to wave at directly, so when a
   nearby block lifts, border-zone neighbours lift together.

   As the picture appears, the four CWCC values light up:
     25%  CHEERFUL      (gold)      — Cheer for opportunities
     50%  WARM          (orange)    — Warmhearted to serve
     75%  COLLABORATIVE (sky blue)  — Collaborate to succeed
     100% CONFIDENT     (cyan)      — Positive & confident
                                     to face the future

   On OpenProcessing:
     1. Upload the school photo as sketch media and name it
        school.jpg  (in the editor: the upload / media button).
     2. Paste this code, press Play, allow the camera.
   ============================================================ */

const W = 960, H = 600;
const VW = 320, VH = 240;        // small camera feed = fast motion detection
const CELL = 24;                 // veil tile size (what is drawn)
const SUB = 3;                   // brush paints at 1/3-tile resolution (8px)
const SCELL = CELL / SUB;        // 8px sub-cell
const COLS = W / CELL, ROWS = H / CELL;
const SCOLS = COLS * SUB, SROWS = ROWS * SUB;
const BRUSH_R = 12;              // round brush radius (px) — a generous dab for little hands
const EDGE_BAND = 8;             // sub-cells (~64px): the frame border zone
const EDGE_LIFT = 0.44;          // border-zone neighbours lift together (+10% kid-easy)
// noise-robust motion: a sample must look "moved" on consecutive frames
// before it may paint — camera flicker / auto-exposure never sustains.
const MOTION_T = 75;             // per-sample RGB change needed — light kid-waves count;
// the 2-frame heat gate (below) still keeps camera noise from painting
const STEP = 4;
const GW = VW / STEP, GH = VH / STEP;
let heat = [];                   // 0..3 per sample; paints only at >= 2

const VALUES = [
  { name: 'CHEERFUL',      hex: '#FBCB09', at: 0.25 },
  { name: 'WARM',          hex: '#FF8400', at: 0.50 },
  { name: 'COLLABORATIVE', hex: '#0083CA', at: 0.75 },
  { name: 'CONFIDENT',     hex: '#35C4FF', at: 1.00 },
];

let schoolImg = null, imgMissing = false;
let video, prevPixels = null;
let camOn = false, camWaiting = true;
let veil = [];          // 0 = covered, 1 = fully revealed
let shown = [false, false, false, false];
let sparks = [];
let floaters = [];
let progress = 0;
let doneCelebrated = false;

function setup() {
  createCanvas(W, H);
  textFont('Trebuchet MS');
  schoolImg = loadImage('data:image/jpeg;base64,',
    () => {},
    () => { imgMissing = true; });
  for (let i = 0; i < SCOLS * SROWS; i++) veil.push(0);
  for (let i = 0; i < GW * GH; i++) heat.push(0);
}

function startCamera() {
  video = createCapture(VIDEO);
  video.size(VW, VH);
  video.hide();
  camOn = true;
}

function coverDraw(img) {
  const s = max(W / img.width, H / img.height);
  const dw = img.width * s, dh = img.height * s;
  image(img, (W - dw) / 2, (H - dh) / 2, dw, dh);
}

function burst(x, y, hex, n) {
  for (let i = 0; i < n; i++) {
    const a = random(TWO_PI), sp = random(1, 6);
    sparks.push({
      x, y, vx: cos(a) * sp, vy: sin(a) * sp - 0.5,
      life: 1, decay: random(0.012, 0.03),
      size: random(3, 9), hex, petal: random() < 0.5,
      rot: random(TWO_PI), rotSp: random(-0.2, 0.2),
    });
  }
}

function word(x, y, txt, hex, size) {
  floaters.push({ x, y, txt, hex, life: 2.2, size: size || 46 });
}

function resetVeil() {
  for (let i = 0; i < veil.length; i++) veil[i] = 0;
  shown = [false, false, false, false];
  doneCelebrated = false;
  floaters = [];
}

function detectMotion() {
  video.loadPixels();
  const p = video.pixels;
  if (p.length > 0) camWaiting = false;
  if (!prevPixels || prevPixels.length !== p.length) {
    prevPixels = p.slice();
    return;
  }
  const step = STEP;
  for (let gy = 0, y = 0; y < VH; gy++, y += step) {
    for (let gx = 0, x = 0; x < VW; gx++, x += step) {
      const i = (y * VW + x) * 4;
      const d = abs(p[i] - prevPixels[i]) + abs(p[i + 1] - prevPixels[i + 1]) + abs(p[i + 2] - prevPixels[i + 2]);
      const hi = gy * GW + gx;
      if (d > MOTION_T) {
        heat[hi] = min(3, heat[hi] + 1);
        if (heat[hi] < 2) continue;   // flicker: moved once, not sustained — ignore
        // mirrored mapping onto the canvas
        const mxx = W - (x / VW) * W;
        const myy = (y / VH) * H;
        // small round brush: only the ~8px sub-cells near the motion point lift
        const sc0 = floor((mxx - BRUSH_R) / SCELL), sc1 = floor((mxx + BRUSH_R) / SCELL);
        const sr0 = floor((myy - BRUSH_R) / SCELL), sr1 = floor((myy + BRUSH_R) / SCELL);
        for (let sr = max(0, sr0); sr <= min(SROWS - 1, sr1); sr++) {
          for (let sc = max(0, sc0); sc <= min(SCOLS - 1, sc1); sc++) {
            const cx = (sc + 0.5) * SCELL, cy = (sr + 0.5) * SCELL;
            const dx = cx - mxx, dy = cy - myy;
            if (dx * dx + dy * dy <= BRUSH_R * BRUSH_R) {
              const idx = sr * SCOLS + sc;
              veil[idx] = min(1, veil[idx] + 0.72);
              // edges & corners are awkward to wave at directly: when a
              // nearby block lifts, border-zone neighbours lift together
              for (let dr = -1; dr <= 1; dr++) {
                for (let dc = -1; dc <= 1; dc++) {
                  if (dr === 0 && dc === 0) continue;
                  const nc = sc + dc, nr = sr + dr;
                  if (nc < 0 || nr < 0 || nc >= SCOLS || nr >= SROWS) continue;
                  const edgeDist = min(nc, nr, SCOLS - 1 - nc, SROWS - 1 - nr);
                  if (edgeDist <= EDGE_BAND) {
                    const nidx = nr * SCOLS + nc;
                    veil[nidx] = min(1, veil[nidx] + EDGE_LIFT);
                  }
                }
              }
            }
          }
        }
        if (random() < 0.3) {
          sparks.push({
            x: mxx + random(-8, 8), y: myy + random(-8, 8),
            vx: random(-1, 1), vy: random(-2, -0.5),
            life: 1, decay: random(0.02, 0.05), size: random(2, 6),
            hex: '#FBCB09', petal: false, rot: 0, rotSp: 0,
          });
        }
      } else {
        heat[hi] = max(0, heat[hi] - 1);
      }
    }
  }
  prevPixels = p.slice();
}

function draw() {
  background(0, 31, 71);

  if (!camOn) { drawStartOverlay(); return; }

  // --- the school photo, full bleed ---
  const photoOK = schoolImg && schoolImg.width > 0 && !imgMissing;
  if (photoOK) {
    coverDraw(schoolImg);
  } else {
    // graceful fallback: painted gradient "campus dusk"
    for (let y = 0; y < H; y += 4) {
      const t = y / H;
      stroke(lerpColor(color('#0B2A5B'), color('#FBCB09'), t * 0.55));
      line(0, y, W, y);
    }
    noStroke(); fill(0, 31, 71, 120); rect(0, 0, W, H);
  }

  detectMotion();

  // --- the navy veil, lifting where there was motion ---
  let sum = 0;
  noStroke();
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      // a tile's openness = average of its 3x3 sub-cells (brush paints at 8px)
      let t = 0;
      for (let sr = 0; sr < SUB; sr++)
        for (let sc = 0; sc < SUB; sc++)
          t += veil[(r * SUB + sr) * SCOLS + c * SUB + sc];
      const v = t / (SUB * SUB);
      sum += t;
      if (v < 0.98) {
        const a = (1 - v) * 238;
        fill(0, 31, 71, a);
        rect(c * CELL, r * CELL, CELL, CELL);
        if (v < 0.05) {
          stroke(251, 203, 9, 22); noFill();
          rect(c * CELL, r * CELL, CELL, CELL);
          noStroke();
        }
      }
    }
  }
  progress = sum / (SCOLS * SROWS);
  // grand finale: at 95% the rest of the veil melts away on its own
  if (progress >= 0.95 && progress < 1) {
    for (let i = 0; i < veil.length; i++) veil[i] = 1;
    progress = 1;
  }

  // --- value milestones ---
  for (let i = 0; i < 4; i++) {
    if (!shown[i] && progress >= VALUES[i].at) {
      shown[i] = true;
      const vx = W / 2, vy = H / 2 - 40;
      burst(vx, vy, VALUES[i].hex, 46);
      word(vx, vy - 70, VALUES[i].name, VALUES[i].hex, 54);
      if (i === 3) {
        word(vx, vy + 130, 'Empowering Global-minded Innovators', '#FBCB09', 28);
        for (let k = 0; k < 6; k++)
          burst(random(W), random(H * 0.7), ['#FBCB09', '#FF8400', '#0083CA', '#35C4FF'][k % 4], 30);
        doneCelebrated = true;
      }
    }
  }

  drawSparks();
  drawFloaters();
  drawHUD();
  drawMiniCam();
  if (!photoOK) drawPhotoNotice();
  if (camWaiting) drawCamWaiting();
}

// Shown ABOVE the veil so it can never be hidden: the photo is missing.
function drawPhotoNotice() {
  const pw = 620, ph = 150, px = W / 2 - pw / 2, py = H / 2 - ph / 2;
  noStroke(); fill(0, 0, 0, 200); rect(px, py, pw, ph, 18);
  stroke(251, 203, 9); strokeWeight(2); noFill(); rect(px, py, pw, ph, 18);
  noStroke(); textAlign(CENTER, CENTER);
  fill(251, 203, 9); textStyle(BOLD); textSize(22);
  text('School photo not found', W / 2, py + 38);
  fill(255, 255, 255, 230); textStyle(NORMAL); textSize(15);
  text('Upload the photo as sketch media named exactly "school.jpg",', W / 2, py + 74);
  text('then press Play again to reveal the real campus picture.', W / 2, py + 98);
  fill(255, 255, 255, 150); textSize(13);
  text('(The veil and values still work — only the photo is missing.)', W / 2, py + 124);
}

// Shown until the first camera frame arrives.
function drawCamWaiting() {
  noStroke(); fill(0, 0, 0, 170);
  const msg = 'Waiting for camera — allow access when the browser asks…';
  textAlign(CENTER, CENTER); textSize(15);
  const tw = textWidth(msg);
  rect(W / 2 - tw / 2 - 18, H - 84, tw + 36, 36, 18);
  fill(255, 255, 255, 230); text(msg, W / 2, H - 66);
}

function drawSparks() {
  for (let i = sparks.length - 1; i >= 0; i--) {
    const s = sparks[i];
    s.x += s.vx; s.y += s.vy; s.vy += 0.06;
    s.life -= s.decay; s.rot += s.rotSp;
    if (s.life <= 0) { sparks.splice(i, 1); continue; }
    const c = color(s.hex); c.setAlpha(s.life * 255);
    push(); translate(s.x, s.y); rotate(s.rot);
    noStroke(); fill(c);
    if (s.petal) ellipse(0, 0, s.size, s.size * 0.55); else circle(0, 0, s.size * 0.55);
    pop();
  }
}

function drawFloaters() {
  textAlign(CENTER, CENTER); textStyle(BOLD);
  for (let i = floaters.length - 1; i >= 0; i--) {
    const f = floaters[i];
    f.y -= 0.6; f.life -= 0.012;
    if (f.life <= 0) { floaters.splice(i, 1); continue; }
    const a = min(1, f.life) * 255;
    const c = color(f.hex); c.setAlpha(a);
    textSize(f.size);
    const tw = textWidth(f.txt);
    noStroke(); fill(0, 31, 71, a * 0.6);
    rect(f.x - tw / 2 - 14, f.y - f.size * 0.72, tw + 28, f.size * 1.44, 16);
    fill(c); text(f.txt, f.x, f.y);
  }
  textStyle(NORMAL);
}

function drawHUD() {
  noStroke(); fill(0, 0, 0, 110); rect(0, 0, W, 64);
  textAlign(LEFT, CENTER); fill(255); textStyle(BOLD); textSize(17);
  text('VALUES REVEAL', 20, 22);
  textStyle(NORMAL); textSize(12); fill(255, 255, 255, 170);
  text('Wave, dance, move — reveal the picture', 20, 46);

  // value chips light up (centred, clear of the title and the progress bar)
  let lx = W / 2 - 195;
  textAlign(CENTER, CENTER);
  for (let i = 0; i < 4; i++) {
    const lit = shown[i];
    fill(color(VALUES[i].hex)); circle(lx, 32, 26);
    if (!lit) { fill(0, 31, 71, 170); circle(lx, 32, 26); }
    fill(lit ? color('#001F47') : color(255, 255, 255, 160));
    textStyle(BOLD); textSize(13); text(VALUES[i].name[0], lx, 33);
    lx += 105;
  }
  textStyle(NORMAL);

  // progress bar (right of the chips, left of reset)
  const bx = W - 285, bw = 150;
  noStroke(); fill(255, 255, 255, 40); rect(bx, 26, bw, 12, 6);
  fill('#FBCB09'); rect(bx, 26, bw * progress, 12, 6);
  fill(255); textAlign(RIGHT, CENTER); textSize(13);
  text(floor(progress * 100) + '% revealed', bx + bw, 52);

  // reset button
  const rx = W - 96, ry = 18, rw = 80, rh = 28;
  const hov = mouseX > rx && mouseX < rx + rw && mouseY > ry && mouseY < ry + rh;
  fill(hov ? color('#FFD93B') : color('#FBCB09')); rect(rx, ry, rw, rh, 14);
  fill(0, 31, 71); textStyle(BOLD); textSize(12); textAlign(CENTER, CENTER);
  text('RESET (R)', rx + rw / 2, ry + rh / 2 + 1);
  textStyle(NORMAL);
}

function drawMiniCam() {
  if (!video) return;
  const mw = 160, mh = 120, mx = 16, my = H - mh - 16;
  push();
  translate(mx + mw, my); scale(-1, 1);
  tint(255, 200); image(video, 0, 0, mw, mh);
  pop();
  noTint();
  noFill(); stroke(251, 203, 9, 160); strokeWeight(2); rect(mx, my, mw, mh, 6);
  noStroke(); fill(255, 255, 255, 200); textAlign(LEFT, CENTER); textSize(12);
  text('you — wave to reveal', mx + mw + 10, my + mh / 2);
}

function drawStartOverlay() {
  // gentle animated backdrop
  noStroke();
  for (let i = 0; i < 70; i++) {
    const x = (i * 167 + frameCount * (0.2 + (i % 5) * 0.15)) % W;
    const y = (i * 251) % H;
    fill(251, 203, 9, 26); circle(x, y, 3 + (i % 4));
  }
  textAlign(CENTER, CENTER);
  fill(251, 203, 9); textStyle(BOLD); textSize(20);
  text('CARITAS WU CHENG-CHUNG COLLEGE', W / 2, 120);
  fill(255, 255, 255, 200); textStyle(NORMAL); textSize(15);
  text('Empowering Global-minded Innovators', W / 2, 148);
  fill(255); textStyle(BOLD); textSize(52);
  text('VALUES REVEAL', W / 2, 225);
  textStyle(NORMAL); textSize(16); fill(255, 255, 255, 220);
  text('A photo of the school hides under a navy veil.', W / 2, 290);
  text('Wave your hands, dance, move — wherever you move, the picture appears.', W / 2, 316);
  textSize(14); fill(255, 255, 255, 170);
  text('Reveal 25 / 50 / 75 / 100% to light up CHEERFUL · WARM · COLLABORATIVE · CONFIDENT.', W / 2, 348);
  text('No body-tracking model needed — just motion. Stand back so the camera sees you.', W / 2, 372);

  const bx = W / 2 - 170, by = 440, bw = 340, bh = 60;
  const hov = mouseX > bx && mouseX < bx + bw && mouseY > by && mouseY < by + bh;
  fill(hov ? color('#FFD93B') : color('#FBCB09')); rect(bx, by, bw, bh, 30);
  fill(0, 31, 71); textStyle(BOLD); textSize(20);
  text('CLICK TO START CAMERA', W / 2, by + bh / 2 + 1);
  textStyle(NORMAL); fill(255, 255, 255, 150); textSize(13);
  text('Tip: stand back so the camera sees you, and wave with big, clear movements.', W / 2, 540);
}

function mousePressed() {
  if (!camOn) {
    const bx = W / 2 - 170, by = 440, bw = 340, bh = 60;
    if (mouseX > bx && mouseX < bx + bw && mouseY > by && mouseY < by + bh) startCamera();
    return;
  }
  const rx = W - 96, ry = 18, rw = 80, rh = 28;
  if (mouseX > rx && mouseX < rx + rw && mouseY > ry && mouseY < ry + rh) resetVeil();
}

function keyPressed() {
  if ((key === 'r' || key === 'R') && camOn) resetVeil();
}
